const NODES=DATA.nodes, LINES=DATA.lines, ZONES=DATA.zones, LINKS=DATA.links, CL=DATA.clusters, NUM=DATA.num;
const EGY={type:'Feature',geometry:GEO.egypt};
const byId=new Map();
NODES.forEach(d=>byId.set(d.id,d)); LINES.forEach(l=>byId.set(l.id,l)); ZONES.forEach(z=>byId.set(z.id,z));
const STEPS=[
 {n:'مصر 2014',t:'نقطة البداية',m:'السكان والأنشطة متركّزة في الوادي والدلتا، على حوالي 7% فقط من مساحة مصر.',k:['built0']},
 {n:'الأرض',t:'إعادة رسم خريطة التنمية',m:'لماذا كان التوسع خارج الرقعة القديمة ضرورة؟ مناطق جديدة تظهر: الساحل الشمالي الغربي، سيناء، إقليم القناة، الصعيد، شرق القاهرة.',k:['built','cities']},
 {n:'الربط',t:'ربط الأرض وفتح مسارات التنمية',m:'لا يمكن تنمية منطقة معزولة عن باقي الاقتصاد. الطرق والمحاور والسكك والموانئ تربط الجديد بمراكز السكان والإنتاج والأسواق.',k:['roads','nileaxes','ports','airports']},
 {n:'الطاقة والمياه',t:'توفير الطاقة والمياه والمرافق',m:'الأرض المتاحة تتحول إلى أرض مهيّأة للتنمية والاستثمار.',k:['power','water','sewage']},
 {n:'المجتمعات',t:'إنشاء المجتمعات العمرانية وتحسين القائم',m:'البنية الأساسية تتحول إلى مجتمعات قابلة للحياة، وليست مجرد منشآت.',k:['cities','units','unsafe']},
 {n:'الإنسان',t:'بناء الإنسان والخدمات',m:'الهدف ليس بناء مدن فقط، وإنما تحسين جودة حياة المواطنين وتأهيل الإنسان.',k:['universities','classrooms','insurance']},
 {n:'الإنتاج',t:'إطلاق النشاط الاقتصادي والإنتاج',m:'الاستثمارات السابقة تتيح فرصًا للإنتاج والتصدير والتشغيل.',k:['reclaim','silos','industry_jobs']},
 {n:'المواطن',t:'المواطن والعائد من التنمية',m:'ما الذي تغيّر فعليًا في حياة المواطن وفي قدرة الاقتصاد المصري؟',k:[]},
 {n:'الصورة الكاملة',t:'مصر شبكة واحدة',m:'المحاور السبعة معًا: عمران وبنية أساسية وإنسان وإنتاج في شبكة واحدة مترابطة.',k:['investment']}
];
const FINAL='ما تحقق لم يكن مجموعة من المشروعات المنفصلة، وإنما عملية متكاملة لإعادة تشكيل خريطة التنمية في مصر.';
const LNAMES=['مصر 2014','الأرض','الربط','الطاقة والمياه والمرافق','المجتمعات العمرانية','الإنسان والخدمات','الإنتاج','المواطن والعائد'];
const CIT=[{k:'hayah',p:[30.9,27.4],dx:-250,dy:-20},{k:'units',p:[31.3,30.05],dx:-280,dy:-150},{k:'tourism_rev',p:[32.64,25.7],dx:60,dy:30},{k:'industry_jobs',p:[32.3,29.68],dx:70,dy:-40},{k:'insurance',p:[32.29,30.6],dx:80,dy:-140},{k:'reclaim',p:[31.4,22.95],dx:-260,dy:-40}];
NUM.built0={v:7,u:'%',l:'المعمور من مساحة مصر'};

/* ---------- helpers ---------- */
const fmt=v=>{if(v==null)return '—';if(typeof v!=='number')return v;return v>=10000?d3.format(',')(v):String(v)};
function numBits(k){const x=NUM[k];if(!x)return null;
  if(x.from!=null&&x.to!=null) return {b:`${fmt(x.from)} ← ${fmt(x.to)}`,u:x.u,l:x.l+(x.sub?` · ${x.sub}`:'')};
  if(x.v==null) return {b:'…',u:'',l:x.l+(x.sub?` · ${x.sub}`:'')};
  return {b:fmt(x.to&&x.v?x.to:x.v),u:x.u,l:x.l+(x.sub?` · ${x.sub}`:'')};}
const SYM={hsrst:'ring',port:'diamond',dry:'diamond',land:'diamond',airport:'triangle',tunnel:'square',nileaxis:'dot',power:'circle',water:'circle',desal:'ring',oil:'wye',digital:'cross',city:'circle',cityold:'circle',slum:'square',uni:'triangle',hosp:'cross',school:'circle',ind:'square',fish:'circle',silo:'dot',tour:'star'};
function rOf(d){switch(d.t){
 case 'power':return 2.6+Math.sqrt(d.v)/10; case 'water':return 2.6+Math.sqrt(d.v)*2.6; case 'city':return d.v?3+Math.sqrt(d.v)/70:3.6;
 case 'cityold':return d.v?2+Math.sqrt(d.v)/95:2.2; case 'school':return 2+Math.sqrt(d.v)/3.6; case 'hosp':return 3.4; case 'uni':return 3.1;
 case 'ind':return 4.2; case 'port':return 4.4; case 'dry':return 3.2; case 'land':return 3; case 'airport':return 3.8; case 'hsrst':return d.hub?5:3.4;
 case 'nileaxis':return 1.7; case 'silo':return 2; case 'tour':return 4.6; case 'tunnel':return 3.6; case 'oil':return 4; default:return 3}}
function symPath(d,scale=1,th){const r=rOf(d)*scale, s=(th&&th.symAll)||SYM[d.t]||'circle';
  if(s==='plus'){const a=Math.max(4,r*1.5);return `M${-a},0H${a}M0,${-a}V${a}`}
  if(s==='circle'||s==='dot'||s==='ring') return d3.symbol(d3.symbolCircle,Math.PI*r*r)();
  const T={diamond:d3.symbolDiamond,triangle:d3.symbolTriangle,square:d3.symbolSquare,cross:d3.symbolCross,wye:d3.symbolWye,star:d3.symbolStar}[s];
  return d3.symbol(T,Math.PI*r*r*1.15)();}
function arcPath(a,b,bend=.18){const dx=b[0]-a[0],dy=b[1]-a[1];const mx=(a[0]+b[0])/2-dy*bend,my=(a[1]+b[1])/2+dx*bend;return `M${a[0]},${a[1]}Q${mx},${my} ${b[0]},${b[1]}`}
function endPt(proj,b){if(typeof b==='string'){const n=byId.get(b);if(!n)return null;const p=n.p||n.c;return p?proj(p):null}return proj(b.pt)}

/* ---------- shared map engine ----------
 th: theme; cfg: {box, links:'arc'|'straight'|false, glow, pulse, labels, nodeFill(d,th), extra(ctx)} */
function baseMap(stage,th,cfg={}){
  const box=cfg.box||[70,40,1080,870];
  const proj=d3.geoMercator().fitExtent([[box[0],box[1]],[box[2],box[3]]],EGY);
  const path=d3.geoPath(proj);
  const svg=d3.select(stage).append('svg').attr('class','map'+(cfg.pulse?' pulse':'')).attr('viewBox',`0 0 ${W} ${H}`);
  const defs=svg.append('defs');
  const gl=defs.append('filter').attr('id','glow').attr('x','-50%').attr('y','-50%').attr('width','200%').attr('height','200%');
  gl.append('feGaussianBlur').attr('stdDeviation',cfg.glowR||3.2).attr('result','b');
  const fm=gl.append('feMerge');fm.append('feMergeNode').attr('in','b');fm.append('feMergeNode').attr('in','SourceGraphic');
  const hp=defs.append('pattern').attr('id','hatch').attr('patternUnits','userSpaceOnUse').attr('width',7).attr('height',7).attr('patternTransform','rotate(35)');
  hp.append('rect').attr('width',7).attr('height',7).attr('fill',th.L[6]).attr('opacity',.18);
  hp.append('line').attr('x1',0).attr('y1',0).attr('x2',0).attr('y2',7).attr('stroke',th.L[6]).attr('stroke-width',2.2).attr('opacity',.8);
  defs.append('clipPath').attr('id','eclip').append('path').attr('d',path(EGY));
  svg.append('rect').attr('width',W).attr('height',H).attr('fill',th.bg);
  if(cfg.pre) cfg.pre(svg,defs);
  const world=svg.append('g').attr('class','world');
  if(cfg.clip){defs.append('clipPath').attr('id','wclip').append('rect').attr('x',cfg.clip[0]).attr('y',cfg.clip[1]).attr('width',cfg.clip[2]).attr('height',cfg.clip[3]).attr('rx',14);svg.append('g').attr('clip-path','url(#wclip)').node().appendChild(world.node())}
  const base=world.append('g');
  if(th.sea) base.append('rect').attr('x',-W).attr('y',-H).attr('width',W*3).attr('height',H*3).attr('fill',th.sea);
  base.append('g').selectAll('path').data(GEO.neighbors).join('path').attr('d',d=>path(d.g)).attr('fill',th.nb).attr('stroke',th.nbs||'none').attr('stroke-width',.6);
  base.append('path').attr('d',path(EGY)).attr('fill',th.land).attr('stroke',th.coast).attr('stroke-width',th.coastW||1).attr('class','cst');
  if(cfg.under) cfg.under(base,{proj,path,svg,defs});
  if(th.gov) base.append('g').selectAll('path').data(GEO.gov).join('path').attr('d',d=>path(d.g)).attr('fill','none').attr('stroke',th.gov).attr('stroke-width',th.govW||.7).attr('class','cst');
  base.append('g').selectAll('path').data(GEO.lakes).join('path').attr('d',d=>path(d.g)).attr('fill',th.water);
  // valley (L0) and zones
  const zg=world.append('g');
  ZONES.forEach(z=>{
    const lay=z.t==='valley'?0:z.L;
    const el=zg.append('path').attr('d',path(z.g)).attr('class',`zn lyr lyr${lay} z-${z.t}`).attr('data-id',z.id);
    if(z.t==='valley') el.attr('fill',th.valley).attr('stroke',th.valleyS||'none').attr('stroke-width',.6);
    else if(z.t==='grow') el.attr('fill',th.grow||th.L[1]).attr('fill-opacity',th.growOp??.28).attr('stroke',th.L[1]).attr('stroke-width',1).attr('stroke-dasharray','4 4');
    else el.attr('fill','url(#hatch)').attr('stroke',th.L[6]).attr('stroke-width',1);
  });
  base.append('g').selectAll('path').data(GEO.nile).join('path').attr('d',d=>path(d.g)).attr('class','cst').attr('fill','none').attr('stroke',th.nile).attr('stroke-width',th.nileW||1.6).attr('filter',cfg.glow?'url(#glow)':null);
  // lines
  const lg=world.append('g');
  const lineW={hsr:2.6,road:1.3,lrt:2.2,mono:2.2,canal:3,digital:1.4};
  LINES.forEach(l=>{
    const d=d3.line()(l.pts.map(p=>proj(p)));
    const c=th.lineC?.[l.t]||th.L[l.L];
    lg.append('path').attr('d',d).attr('class',`ln draw lyr lyr${l.L} t-${l.t}`).attr('data-id',l.id).attr('stroke',c).attr('stroke-width',(th.lineW?.[l.t])||lineW[l.t]||1.4)
      .attr('stroke-dasharray',l.t==='digital'?'5 5':(l.t==='road'&&th.roadDash?th.roadDash:null)).attr('stroke-linecap','round').attr('stroke-linejoin','round').attr('filter',cfg.glow&&l.t!=='road'?'url(#glow)':null);
    if(cfg.pulse&&(l.t==='hsr'||l.t==='lrt'||l.t==='mono'||l.t==='canal')) lg.append('path').attr('d',d).attr('class',`ln flow lyr lyr${l.L}`).attr('data-id',l.id).attr('stroke',th.pulseC||'#fff').attr('stroke-width',2.4).attr('stroke-dasharray','2 56').attr('stroke-linecap','round').attr('fill','none');
  });
  // links
  const kg=world.append('g');
  if(cfg.links!==false){
    LINKS.forEach(k=>{
      const a=endPt(proj,k.a), b=endPt(proj,k.b); if(!a||!b) return;
      const bid=typeof k.b==='string'?k.b:k.b.line;
      const d=cfg.links==='straight'?`M${a}L${b}`:arcPath(a,b,cfg.bend??.2);
      kg.append('path').attr('d',d).attr('class',`lk lk${k.L} k-${k.k}`).attr('data-a',k.a).attr('data-b',bid).attr('stroke',th.linkC?th.linkC(k):th.L[k.L]).attr('stroke-width',th.linkW||1.1).attr('stroke-dasharray',th.linkDash||null);
    });
  }
  // nodes
  const ng=world.append('g');
  const nodeSel=ng.selectAll('g').data(NODES).join('g').attr('class',d=>`nd lyr lyr${d.L} t-${d.t}${d.hub?' hub':''}`).attr('data-id',d=>d.id)
    .attr('transform',d=>{const p=proj(d.p);return `translate(${p[0]},${p[1]})`});
  const inner=nodeSel.append('g').attr('class','ni');
  inner.append('path').attr('d',d=>symPath(d,th.symK||1,th)).attr('fill',d=>th.nodeFill?th.nodeFill(d):(SYM[d.t]==='ring'?th.bg:th.L[d.L])).attr('stroke',d=>th.nodeStroke?th.nodeStroke(d):(SYM[d.t]==='ring'?th.L[d.L]:(th.nodeS||'none'))).attr('stroke-width',d=>SYM[d.t]==='ring'?1.6:(th.nodeSW||.8)).attr('fill-opacity',d=>d.t==='school'?.55:(th.nodeOp||1)).attr('filter',d=>cfg.glow&&(d.hub||d.t==='power'||d.t==='water')?'url(#glow)':null);
  // labels (hubs + all in groups for focus)
  const lab=world.append('g');
  const labSel=lab.selectAll('g').data(NODES.filter(d=>d.t!=='nileaxis'&&d.t!=='school')).join('g').attr('class',d=>`lb lbl${d.L}${d.hub?' hub':''}`).attr('data-id',d=>d.id)
    .attr('transform',d=>{const p=proj(d.p);return `translate(${p[0]},${p[1]})`});
  labSel.append('g').attr('class','ni').append('text').text(d=>d.n.replace(/^(محطة|ميناء|مطار|جامعة|مستشفى|صومعة|محطة معالجة) /,'')).attr('x',-9).attr('y',4).attr('text-anchor','start')
    .attr('font-size',th.labelSize||13).attr('fill',th.text).attr('stroke',th.halo||th.bg).attr('stroke-width',3.2).attr('paint-order','stroke').attr('stroke-linejoin','round');
  // zone labels at step 1 and valley at 0
  const zl=world.append('g');
  ZONES.filter(z=>z.t==='grow'||z.t==='valley').forEach(z=>{
    const c=d3.geoCentroid(z.g), p=proj(c);
    const off={'الوادي والدلتا — المعمور 2014':[40,-60],'سيناء':[10,-5],'إقليم قناة السويس':[-60,-60],'شرق القاهرة والعاصمة':[-8,-36],'الظهير الصحراوي للصعيد':[-90,40],'غرب الدلتا':[-10,-26],'ساحل البحر الأحمر':[40,40]}[z.n]||[0,0];
    zl.append('text').attr('class',`lb lbl${z.t==='valley'?0:1}`).attr('x',p[0]+off[0]).attr('y',p[1]+off[1]).attr('text-anchor','middle')
      .attr('font-size',z.t==='valley'?16:14.5).attr('font-weight',500).attr('fill',z.t==='valley'?th.text:(th.zoneText||th.L[1])).attr('stroke',th.halo||th.bg).attr('stroke-width',3.4).attr('paint-order','stroke')
      .text(z.t==='valley'?'الوادي والدلتا · 7%':z.n);
  });
  const ov=world.append('g');
  const ctx={svg,proj,path,world,box,th,cfg,ov,nodeSel,labSel,k:1,tx:0,ty:0,stage};
  if(cfg.extra) cfg.extra(ctx);
  ctx.step=s=>engineStep(ctx,s);
  ctx.focus=ci=>engineFocus(ctx,ci);
  return ctx;
}
function engineStep(ctx,s){
  const el=ctx.svg.node();
  for(let l=0;l<=7;l++){el.classList.toggle('on'+l,s>=l&&s<8||s===8);el.classList.toggle('cur'+l,s===l)}
  el.classList.toggle('all',s===8); el.classList.toggle('s7',s===7);
  // draw-in lines of the current layer
  if(s>=1&&s<=6){
    ctx.svg.selectAll(`.draw.lyr${s}`).each(function(){const L=this.getTotalLength();d3.select(this).interrupt().attr('stroke-dasharray',`${L} ${L}`).attr('stroke-dashoffset',L)
      .transition().duration(1800).ease(d3.easeCubicInOut).attr('stroke-dashoffset',0).on('end',function(){const t=d3.select(this);if(!t.classed('t-digital')&&!(t.classed('t-road')&&ctx.th.roadDash))t.attr('stroke-dasharray',null);else t.attr('stroke-dasharray',t.classed('t-digital')?'5 5':ctx.th.roadDash)})});
  }
  // light up what the current layer depends on
  const lit=new Set(); if(s>=3&&s<=6) LINKS.forEach(k=>{if(k.L===s){lit.add(typeof k.b==='string'?k.b:k.b.line)}});
  ctx.svg.selectAll('.nd,.ln').classed('lit',function(){return lit.has(this.dataset.id)});
  if(ctx.onStep) ctx.onStep(s);
}
function engineFocus(ctx,ci){
  const el=ctx.svg.node();
  ctx.svg.selectAll('.fc').classed('fc',false);
  let k=1,tx=0,ty=0;
  if(ci>=0){
    const c=CL[ci]; const p=ctx.proj(c.c); k=c.z;
    const cx=(ctx.box[0]+ctx.box[2])/2, cy=(ctx.box[1]+ctx.box[3])/2; tx=cx-p[0]*k; ty=cy-p[1]*k;
    const ids=new Set(); Object.entries(c.steps).forEach(([l,arr])=>{if(+l<=Math.max(state.step,2)||state.step>=7)arr.forEach(i=>ids.add(i))});
    ctx.svg.selectAll('.nd,.ln,.zn,.lb').classed('fc',function(){return ids.has(this.dataset.id)});
    ctx.svg.selectAll('.lk').classed('fc',function(){return ids.has(this.dataset.a)&&ids.has(this.dataset.b)});
    el.classList.add('focus');
  } else el.classList.remove('focus');
  const k0=ctx.k,tx0=ctx.tx,ty0=ctx.ty;
  ctx.world.transition().duration(1300).ease(d3.easeCubicInOut).tween('z',()=>t=>{
    const kk=k0+(k-k0)*t, xx=tx0+(tx-tx0)*t, yy=ty0+(ty-ty0)*t;
    ctx.world.attr('transform',`translate(${xx},${yy}) scale(${kk})`);
    ctx.svg.selectAll('.ni').attr('transform',`scale(${1/kk})`);
  }).on('end',()=>{ctx.k=k;ctx.tx=tx;ctx.ty=ty});
}
/* overlays shared by most treatments */
function addCaption(stage,o){
  const d=document.createElement('div');d.className='cap';d.innerHTML='<div class="n"><i></i><span></span></div><div class="t"></div><div class="m"></div><div class="k"></div>';stage.appendChild(d);
  const lg=document.createElement('div');lg.className='leg';lg.innerHTML=LNAMES.slice(1).map((n,i)=>`<div data-l="${i+1}"><i style="background:${o.th.L[i+1]}"></i>${n}</div>`).join('');stage.appendChild(lg);
  const f=document.createElement('div');f.className='fin';f.textContent=FINAL;stage.appendChild(f);
  return s=>{const st=STEPS[s];
    d.querySelector('.n span').textContent=s===0?'قبل البداية':(s===8?'القفلة':`المحور ${s} من 7`);
    d.querySelector('.t').textContent=st.t; d.querySelector('.m').textContent=st.m;
    d.style.setProperty('--s-acc',o.th.L[Math.min(s,7)]||o.th.text);
    const keys=(s===7&&o.cit7)?['hayah','units','insurance','industry_jobs','tourism_rev','time']:(st.k||[]);
    d.querySelector('.k').innerHTML=keys.map(k=>{const b=numBits(k);return b?`<div><b>${b.b}<small>${b.u}</small></b><span>${b.l}</span></div>`:''}).join('');
    lg.querySelectorAll('div').forEach(x=>{const l=+x.dataset.l;x.className=(s===8||l<s)?'done':(l===s?'cur':'');if(s===8)x.className='cur'});
  };
}
function addCitizen(stage,ctx,o){
  const g=ctx.ov.append('g').attr('class','lyr lyr7 citz');
  CIT.forEach(c=>{const p=ctx.proj(c.p);const b=numBits(c.k);
    g.append('circle').attr('cx',p[0]).attr('cy',p[1]).attr('r',5).attr('fill',o.th.L[7]);
    g.append('path').attr('d',`M${p[0]},${p[1]}L${p[0]+c.dx},${p[1]+c.dy}`).attr('stroke',o.th.L[7]).attr('stroke-width',1).attr('fill','none');
    const card=document.createElement('div');card.className='kcard';card.style.left=(p[0]+c.dx-(c.dx<0?210:0))+'px';card.style.top=(p[1]+c.dy-22)+'px';
    card.innerHTML=`<b>${b.b}<small>${b.u}</small></b><span>${b.l}</span>`;stage.appendChild(card);
  });
}
function stageVars(stage,th){stage.style.setProperty('--s-fg',th.text);stage.style.setProperty('--s-sub',th.sub);stage.style.background=th.bg}

